package com.sistema.academia.config.excepition.handler;

import com.sistema.academia.config.excepition.EntityNotFoundException;
import com.sistema.academia.config.excepition.response.ErroPadraoResponse;
import com.sistema.academia.config.excepition.response.ErroValidacaoResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.NoHandlerFoundException;

@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * Trata IllegalArgumentException e outras exceções de validação de negócio
     */
    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ErroPadraoResponse> handleIllegalArgumentException(
            IllegalArgumentException ex, WebRequest request) {

        ErroPadraoResponse erro = new ErroPadraoResponse(
            HttpStatus.BAD_REQUEST.value(),
            ex.getMessage(),
            request.getDescription(false).replace("uri=", "")
        );

        return ResponseEntity
            .status(HttpStatus.BAD_REQUEST)
            .body(erro);
    }

    /**
     * Trata MethodArgumentNotValidException (validações com @Valid)
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErroValidacaoResponse> handleMethodArgumentNotValid(
            MethodArgumentNotValidException ex, WebRequest request) {

        ErroValidacaoResponse erro = new ErroValidacaoResponse(
            422,
            "Erro de validação nos campos solicitados",
            request.getDescription(false).replace("uri=", "")
        );

        ex.getBindingResult().getFieldErrors().forEach(fieldError ->
            erro.adicionarErro(
                fieldError.getField(),
                fieldError.getDefaultMessage()
            )
        );

        return ResponseEntity
            .status(422)
            .body(erro);
    }

    /**
     * Trata EntityNotFoundException
     */
    @ExceptionHandler(EntityNotFoundException.class)
    public ResponseEntity<ErroPadraoResponse> handleEntityNotFoundException(
            EntityNotFoundException ex, WebRequest request) {

        ErroPadraoResponse erro = new ErroPadraoResponse(
            HttpStatus.NOT_FOUND.value(),
            ex.getMessage(),
            request.getDescription(false).replace("uri=", "")
        );

        return ResponseEntity
            .status(HttpStatus.NOT_FOUND)
            .body(erro);
    }

    /**
     * Trata NoHandlerFoundException (endpoint não encontrado)
     */
    @ExceptionHandler(NoHandlerFoundException.class)
    public ResponseEntity<ErroPadraoResponse> handleNoHandlerFound(
            NoHandlerFoundException ex, WebRequest request) {

        ErroPadraoResponse erro = new ErroPadraoResponse(
            HttpStatus.NOT_FOUND.value(),
            "Endpoint não encontrado: " + ex.getRequestURL(),
            request.getDescription(false).replace("uri=", "")
        );

        return ResponseEntity
            .status(HttpStatus.NOT_FOUND)
            .body(erro);
    }

    /**
     * Trata NumberFormatException
     */
    @ExceptionHandler(NumberFormatException.class)
    public ResponseEntity<ErroPadraoResponse> handleNumberFormatException(
            NumberFormatException ex, WebRequest request) {

        ErroPadraoResponse erro = new ErroPadraoResponse(
            HttpStatus.BAD_REQUEST.value(),
            "Formato de número inválido: " + ex.getMessage(),
            request.getDescription(false).replace("uri=", "")
        );

        return ResponseEntity
            .status(HttpStatus.BAD_REQUEST)
            .body(erro);
    }

    /**
     * Trata exceções genéricas não previstas
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErroPadraoResponse> handleGenericException(
            Exception ex, WebRequest request) {

        ErroPadraoResponse erro = new ErroPadraoResponse(
            HttpStatus.INTERNAL_SERVER_ERROR.value(),
            "Erro interno do servidor: " + ex.getMessage(),
            request.getDescription(false).replace("uri=", "")
        );

        return ResponseEntity
            .status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(erro);
    }

    /**
     * Trata IllegalStateException
     */
    @ExceptionHandler(IllegalStateException.class)
    public ResponseEntity<ErroPadraoResponse> handleIllegalStateException(
            IllegalStateException ex, WebRequest request) {

        ErroPadraoResponse erro = new ErroPadraoResponse(
            HttpStatus.CONFLICT.value(),
            ex.getMessage(),
            request.getDescription(false).replace("uri=", "")
        );

        return ResponseEntity
            .status(HttpStatus.CONFLICT)
            .body(erro);
    }
}

package com.sistema.academia.config.excepition.response;

import java.time.LocalDateTime;

public class ErroPadraoResponse {

    private LocalDateTime timestamp;
    private int status;
    private String mensagem;
    private String caminho;

    public ErroPadraoResponse() {
        this.timestamp = LocalDateTime.now();
    }

    public ErroPadraoResponse(int status, String mensagem, String caminho) {
        this();
        this.status = status;
        this.mensagem = mensagem;
        this.caminho = caminho;
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(LocalDateTime timestamp) {
        this.timestamp = timestamp;
    }

    public int getStatus() {
        return status;
    }

    public void setStatus(int status) {
        this.status = status;
    }

    public String getMensagem() {
        return mensagem;
    }

    public void setMensagem(String mensagem) {
        this.mensagem = mensagem;
    }

    public String getCaminho() {
        return caminho;
    }

    public void setCaminho(String caminho) {
        this.caminho = caminho;
    }
}

package com.sistema.academia.config.excepition.response;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

public class ErroValidacaoResponse {

    private LocalDateTime timestamp;
    private int status;
    private String mensagem;
    private String caminho;
    private List<ErroDetalhado> erros;

    public ErroValidacaoResponse() {
        this.timestamp = LocalDateTime.now();
        this.erros = new ArrayList<>();
    }

    public ErroValidacaoResponse(int status, String mensagem, String caminho) {
        this();
        this.status = status;
        this.mensagem = mensagem;
        this.caminho = caminho;
    }

    public void adicionarErro(String campo, String mensagem) {
        this.erros.add(new ErroDetalhado(campo, mensagem));
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(LocalDateTime timestamp) {
        this.timestamp = timestamp;
    }

    public int getStatus() {
        return status;
    }

    public void setStatus(int status) {
        this.status = status;
    }

    public String getMensagem() {
        return mensagem;
    }

    public void setMensagem(String mensagem) {
        this.mensagem = mensagem;
    }

    public String getCaminho() {
        return caminho;
    }

    public void setCaminho(String caminho) {
        this.caminho = caminho;
    }

    public List<ErroDetalhado> getErros() {
        return erros;
    }

    public void setErros(List<ErroDetalhado> erros) {
        this.erros = erros;
    }

    // Classe aninhada para representar um erro detalhado
    public static class ErroDetalhado {
        private String campo;
        private String mensagem;

        public ErroDetalhado(String campo, String mensagem) {
            this.campo = campo;
            this.mensagem = mensagem;
        }

        public String getCampo() {
            return campo;
        }

        public void setCampo(String campo) {
            this.campo = campo;
        }

        public String getMensagem() {
            return mensagem;
        }

        public void setMensagem(String mensagem) {
            this.mensagem = mensagem;
        }
    }
}

